  window.__KEEP_IDS__ = JSON.parse(atob(parts.join('')));
  const keep = new Set(window.__KEEP_IDS__);
  const deleteIds = new Set(window.__DELETE_IDS__ || []);
  const rootEl = document.querySelector('#root');
  const fiberKey = Object.keys(rootEl).find(k => k.startsWith('__reactFiber') || k.startsWith('__reactContainer'));
  function findStates() {
    let fiber = rootEl[fiberKey];
    let nodeState=null, projState=null;
    const seen=new WeakSet();
    (function walk(node, depth) {
      if (!node || depth>100) return;
      if (seen.has(node)) return;
      seen.add(node);
      let s=node.memoizedState, hops=0;
      while (s && hops<150) {
        const val=s.memoizedState;
        if (val && typeof val==='object') {
          if (Array.isArray(val.nodes) && val.nodes.length>50) nodeState=val;
          if (typeof val.hideScreens==='function' && val.projectId) projState=val;
        }
        s=s.next; hops++;
      }
      walk(node.child, depth+1); walk(node.sibling, depth+1);
    })(fiber.stateNode && fiber.stateNode.current || fiber.child || fiber, 0);
    return {nodeState, projState};
  }
  let {nodeState, projState} = findStates();
  const onCanvas = new Set(nodeState.nodes.map(n=>n.id));
  const keepHidden = nodeState.nodes.filter(n => keep.has(n.id) && n.hidden).map(n=>n.id);
  const keepMissing = [...keep].filter(id => !onCanvas.has(id));
  const deleteVisible = nodeState.nodes.filter(n => deleteIds.has(n.id) && !n.hidden).map(n=>n.id);
  if (keepHidden.length) {
    projState.applyMutations({
      screenInstanceMutations: keepHidden.map(id => ({type:'UPDATE_INSTANCE', id, updates:{hidden:false}}),
      saveStatus: 'dirty'
    });
  }
  await new Promise(r=>setTimeout(r,2500));
  ({nodeState} = findStates());
  return {
    keepCount: keep.size,
    keepHiddenBefore: keepHidden.length,
    keepMissingFromCanvas: keepMissing.length,
    deleteVisibleCount: deleteVisible.length,
    afterVisible: nodeState.nodes.filter(n=>!n.hidden).length,
    afterHidden: nodeState.nodes.filter(n=>n.hidden).length,
    keepStillHidden: nodeState.nodes.filter(n => keep.has(n.id) && n.hidden).length,
    visibleKeep: nodeState.nodes.filter(n => keep.has(n.id) && !n.hidden).length
  };
}
